[
  {
    "sys_rule_justification": "when someone is in danger and you can help without risk, you're obliged to act."
  },
  {
    "sys_rule_justification": "the duty not to stand by while people are in peril would win out"
  },
  {
    "sys_rule_justification": "if you can rescue someone at no risk, you must."
  },
  {
    "sys_rule_justification": "I believe we owe help to anyone in danger."
  },
  {
    "sys_rule_justification": "you don't walk past someone who needs help when helping puts nobody at risk."
  },
  {
    "sys_rule_justification": "every person has a right to have strangers step in when their life is threatened."
  },
  {
    "sys_rule_justification": "That's a principle I hold above station policy.",
    "sys_contextual_flexibility": "rules like that give way when a life is on the line."
  },
  {
    "sys_rule_justification": "My faith teaches that you're commanded to help your neighbor in trouble"
  },
  {
    "sys_rule_justification": "the duty to warn comes before the duty to meddle with things"
  },
  {
    "sys_rule_justification": "it's wrong to stand idle when you could rescue someone safely."
  }
]
